#!/usr/bin/env bash
# Writes app/android/stand.properties for a debug build against the devices stand
# (p1/stand/devices: run ./up.sh there first — it creates out/server.key and out/backup.key).
set -euo pipefail
cd "$(dirname "$0")/.."
STAND=../p1/stand/devices
pin() { openssl pkey -in "$1" -pubout -outform DER 2>/dev/null | openssl dgst -sha256 -binary | base64; }
[[ -f $STAND/out/server.key && -f $STAND/out/backup.key ]] || { echo "no $STAND/out/{server,backup}.key — run $STAND/up.sh" >&2; exit 1; }
cat > android/stand.properties <<PROPS
# generated by tools/stand-config.sh — devices stand via adb reverse
wolp.enrollUrl=https://localhost:9443
wolp.appUrl=https://localhost:9444
wolp.serverPins=sha256/$(pin $STAND/out/server.key),sha256/$(pin $STAND/out/backup.key)
wolp.extraTrustAnchor=../../p1/stand/devices/pki/stand-root.pem
PROPS
cat android/stand.properties
